
const pages=[['pretest','Pre-test'],['materi','Materi'],['budgeting','Budgeting bulanan'],['nutrition','Nutrisi harian'],['time','Audit waktu'],['posttest','Post-test']];const days=['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'];const acts=['Tidur','Waktu Pribadi','Perjalanan & Bekerja','Tugas Rumah','Keluarga','Sosial'];const meals=['Makan pagi','Makan siang','Makan malam'];const nutrients=['Protein','Serat/Sayuran','Biji-bijian','Buah/Vitamin','Others'];const budgetGroups=[['Pemasukan',['Gaji','Penghasilan pasangan','Penghasilan lain']],['Pengeluaran reguler',['Kebutuhan rutin 1','Kebutuhan rutin 2']],['Cicilan / utang',['Cicilan 1','Cicilan 2']],['Tabungan',['Tujuan jangka pendek','Tujuan jangka menengah','Tujuan jangka panjang']],['Pengeluaran lain',['Donasi','Kehidupan sosial','Keluarga']],['Dana darurat',['Dana darurat']],['Lain-lain',['Lain-lain']]];let state;try{state=JSON.parse(localStorage.getItem('rise-demo-v1'))||{}}catch{state={}};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=k=>state[k]??'';const selectedMonth=()=>val('budget-period')||keyMonth();const bkey=(gi,i)=>`budget:${selectedMonth()}:b-${gi}-${i}`;const actualItems=()=>Array.isArray(state.actualExpenses)?state.actualExpenses:[];const monthItems=()=>actualItems().filter(x=>x.date?.startsWith(selectedMonth()));const n=k=>Number(val(k))||0;const money=v=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v);const hour=v=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(v);const pagePeriod=()=>monthLabel();const period=()=>new Date().toLocaleDateString('id-ID',{month:'long',year:'numeric'});const keyMonth=()=>new Date().toISOString().slice(0,7);function input(k,type='text',placeholder=''){return `<input class="form-control form-control-sm" data-key="${k}" type="${type==='number'?'text':type}" ${type==='number'?'inputmode="decimal" autocomplete="off"':''} value="${esc(val(k))}" placeholder="${placeholder}">`}function save(){localStorage.setItem('rise-demo-v1',JSON.stringify(state));document.querySelectorAll('.saved').forEach(e=>e.textContent='Tersimpan di perangkat ini')}const bids=gi=>Array.isArray(state.budgetIds?.[gi])?state.budgetIds[gi]:budgetGroups[gi][1].map((_,i)=>String(i));const bnamekey=(gi,id)=>`budget-name:${gi}:${id}`;const bdefault=(gi,id)=>/^\d+$/.test(id)?(budgetGroups[gi][1][Number(id)]||''):'';const nameInput=(gi,id)=>{const k=bnamekey(gi,id),h=input(k,'text','Nama item');return state[k]===undefined?h.replace('value=""','value="'+esc(bdefault(gi,id))+'"'):h};const nids=m=>Array.isArray(state.nutIds?.[m])?state.nutIds[m]:nutrients.map((_,i)=>String(i));const ntypekey=(m,id)=>`n-${m}-${id}-type`;const ntypeVal=(m,id)=>state[ntypekey(m,id)]??(/^\d+$/.test(id)?(nutrients[Number(id)]||''):'');const typeSelect=(m,id)=>{const cls=input('x').match(/class="([^"]*)"/)[1].replace('form-control','form-select'),cur=ntypeVal(m,id),list=nutrients.includes(cur)||!cur?nutrients:nutrients.concat(cur);return `<select class="${cls}" data-key="${ntypekey(m,id)}" aria-label="Jenis nutrisi"><option value="">Pilih jenis</option>${list.map(x=>`<option value="${esc(x)}"${x===cur?' selected':''}>${esc(x)}</option>`).join('')}</select>`};function sums(){const b=budgetGroups.map((g,gi)=>bids(gi).reduce((s,id)=>s+n(bkey(gi,id)),0));let nutrition=0;for(let m=0;m<3;m++)nutrition+=nids(m).reduce((a,id)=>a+n(`n-${m}-${id}-price`),0);const times=acts.map((_,a)=>days.reduce((s,__,d)=>s+n(`t-${a}-${d}`),0));const actual=budgetGroups.map((_,gi)=>monthItems().filter(x=>Number(x.category)===gi).reduce((total,x)=>total+(Number(x.amount)||0),0));return{b,nutrition,times,total:times.reduce((a,b)=>a+b,0),expenses:b.slice(1).reduce((a,b)=>a+b,0),actual,actualTotal:actual.slice(1).reduce((a,b)=>a+b,0)}}function heading(title,desc){return `<header class="top"><div><div class="eyebrow">RISE Training</div><h1>${title}</h1><p>${desc}</p></div><div class="period">${pagePeriod()}</div></header>`}if(!state.budgetMigrated){let changed=false;for(let gi=0;gi<budgetGroups.length;gi++)for(let i=0;i<budgetGroups[gi][1].length;i++){const old=`b-${gi}-${i}`;if(state[old]!==undefined){state[`budget:${selectedMonth()}:${old}`]=state[old];changed=true}}state.budgetMigrated=true;if(changed)localStorage.setItem('rise-demo-v1',JSON.stringify(state))}const expenseColors=['#1b8976','#368fc6','#ef9e4c','#8471bb','#e06c75','#536b82'];function pieChart(values){const total=values.reduce((a,b)=>a+b,0);if(!total)return '<div class="chart-empty">Belum ada pengeluaran aktual pada bulan ini. Tambahkan transaksi untuk melihat grafik.</div>';if(values.filter(Boolean).length===1){const index=values.findIndex(Boolean);return `<div class="chart-layout"><svg viewBox="0 0 200 200" role="img" aria-label="Pengeluaran aktual per kategori, total ${money(total)}" class="pie"><circle cx="100" cy="100" r="81" fill="${expenseColors[index]}"/><circle cx="100" cy="100" r="40" fill="white"/><text x="100" y="96" text-anchor="middle" class="pie-label">Total aktual</text><text x="100" y="112" text-anchor="middle" class="pie-value">${new Intl.NumberFormat('id-ID',{notation:'compact',maximumFractionDigits:1}).format(total)}</text></svg><div class="legend"><div class="legend-row"><span class="swatch" style="background:${expenseColors[index]}"></span><span>${budgetGroups[index+1][0]}</span><strong>${money(total)} · 100%</strong></div></div></div>`}let start=0;const segments=values.map((v,i)=>{if(!v)return '';const a=start/total*2*Math.PI,b=(start+v)/total*2*Math.PI;start+=v;const pt=t=>[100+81*Math.sin(t),100-81*Math.cos(t)];const q=pt(a),r=pt(b);return `<path d="M 100 100 L ${q[0]} ${q[1]} A 81 81 0 ${b-a>Math.PI?1:0} 1 ${r[0]} ${r[1]} Z" fill="${expenseColors[i]}"/>`}).join('');return `<div class="chart-layout"><svg viewBox="0 0 200 200" role="img" aria-label="Pengeluaran aktual per kategori, total ${money(total)}" class="pie">${segments}<circle cx="100" cy="100" r="40" fill="white"/><text x="100" y="96" text-anchor="middle" class="pie-label">Total aktual</text><text x="100" y="112" text-anchor="middle" class="pie-value">${new Intl.NumberFormat('id-ID',{notation:'compact',maximumFractionDigits:1}).format(total)}</text></svg><div class="legend">${values.map((v,i)=>v?`<div class="legend-row"><span class="swatch" style="background:${expenseColors[i]}"></span><span>${budgetGroups[i+1][0]}</span><strong>${money(v)} · ${Math.round(v/total*100)}%</strong></div>`:'').join('')}</div></div>`}function evaluation(s){return `<section class="panel eval"><h2>Evaluasi anggaran · ${monthLabel()}</h2><div class="table-wrap"><table><thead><tr><th>Kategori</th><th class="num">Anggaran</th><th class="num">Aktual</th><th class="num">Sisa / lebih</th><th>Status</th></tr></thead><tbody>${budgetGroups.slice(1).map((g,i)=>{const gi=i+1,d=s.b[gi]-s.actual[gi];return `<tr><td>${g[0]}</td><td class="num">${money(s.b[gi])}</td><td class="num">${money(s.actual[gi])}</td><td class="num">${money(Math.abs(d))}</td><td><span class="status ${d<0?'over':'under'}">${d<0?'Over budget':s.actual[gi]===0&&s.b[gi]===0?'Belum dianggarkan':'Under budget'}</span></td></tr>`}).join('')}</tbody></table></div><div class="summary"><span>Total anggaran ${money(s.expenses)} · Aktual ${money(s.actualTotal)}</span><strong class="${s.actualTotal>s.expenses?'warning':''}">${s.actualTotal>s.expenses?'Over budget':'Sisa anggaran'} ${money(Math.abs(s.expenses-s.actualTotal))}</strong></div></section>`}function monthLabel(){const [y,m]=selectedMonth().split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('id-ID',{month:'long',year:'numeric'})}function expenseForm(){return `<section class="panel"><h2>Catat pengeluaran</h2><form id="expenseForm" class="expense-form"><div class="field"><label for="expense-date">Tanggal</label><input id="expense-date" name="date" type="date" value="${selectedMonth()===keyMonth()?new Date().toISOString().slice(0,10):selectedMonth()+'-01'}" required></div><div class="field"><label for="expense-category">Kategori anggaran</label><select id="expense-category" name="category" required>${budgetGroups.slice(1).map((g,i)=>`<option value="${i+1}">${g[0]}</option>`).join('')}</select></div><div class="field"><label for="expense-amount">Nominal (Rp)</label><input id="expense-amount" name="amount" type="number" min="1" step="1" placeholder="0" required></div><div class="field"><label for="expense-note">Keterangan</label><input id="expense-note" name="note" maxlength="120" placeholder="Contoh: belanja bulanan"></div><button type="submit" class="primary">Simpan pengeluaran</button></form><p class="hint">Transaksi akan masuk ke evaluasi berdasarkan bulan pada tanggal yang dipilih.</p></section>`}function expenseList(){const rows=monthItems().slice().sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);return `<section class="panel"><h2>Riwayat pengeluaran · ${monthLabel()}</h2>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Kategori</th><th>Keterangan</th><th class="num">Nominal</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td>${budgetGroups[x.category]?.[0]||'Lain-lain'}</td><td>${esc(x.note||'—')}</td><td class="num">${money(Number(x.amount)||0)}</td><td><button class="delete-expense" data-delete="${esc(x.id)}" aria-label="Hapus pengeluaran ${esc(x.note||x.date)}">Hapus</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Belum ada transaksi untuk bulan ini.</p>'}</section>`}function render(){let page=location.hash.slice(1)||'pretest';if(!pages.some(p=>p[0]===page))page='pretest';for(const id of ['nav','mobileNav'])document.getElementById(id).innerHTML=pages.map(([p,t])=>`<button class="nav-link text-start ${page===p?'active':''}" onclick="location.hash='${p}'">${t}</button>`).join('');const s=sums();let html='';if(RX.has(page)){html=RX.page(page,{heading,input})}else if(page==='dashboard'){html=heading('Dashboard','Ringkasan anggaran, pengeluaran aktual, nutrisi, dan waktu.')+`<div class="toolbar"><div><label>Bulan evaluasi</label><input type="month" data-key="budget-period" value="${esc(selectedMonth())}"></div></div><div class="row g-3"><div class="col-12 col-lg-4"><div class="card shadow-sm border-0 h-100 p-4"><div class="mini">Sisa pemasukan setelah pengeluaran</div><div class="value">${money(s.b[0]-s.actualTotal)}</div><div class="note">Pemasukan ${money(s.b[0])} · Pengeluaran aktual ${money(s.actualTotal)}</div></div></div><div class="col-12 col-lg-4"><div class="card shadow-sm border-0 h-100 p-4"><div class="mini">Biaya makan tercatat</div><div class="value">${money(s.nutrition)}</div><div class="note">Total menu pagi, siang, dan malam</div></div></div><div class="col-12 col-lg-4"><div class="card shadow-sm border-0 h-100 p-4"><div class="mini">Jam aktivitas seminggu</div><div class="value">${hour(s.total)} / 168 jam</div><div class="note">${s.total>168?'Melebihi 168 jam; periksa input':'Dari audit waktu Senin–Minggu'}</div></div></div></div><section class="panel chart-panel"><div class="chart-heading"><div><h2>Pengeluaran aktual per kategori</h2><p>${monthLabel()}</p></div><button class="primary" onclick="location.hash='expenses'">Catat pengeluaran</button></div>${pieChart(s.actual.slice(1))}</section>${evaluation(s)}<div class="section-head"><div><h2>Buka worksheet</h2><p>Isi setiap halaman sesuai periode pencatatan.</p></div></div><div class="row g-3"><div class="col-12 col-lg-4"><article class="card border-0 shadow-sm h-100 p-4 tile"><div class="icon">▤</div><h3>Budgeting bulanan</h3><p>Catat pemasukan, pengeluaran, cicilan, tabungan, dan dana darurat.</p><button class="btn btn-primary" onclick="location.hash='budgeting'">Buka budgeting</button></article></div><div class="col-12 col-lg-4"><article class="card border-0 shadow-sm h-100 p-4 tile"><div class="icon">◉</div><h3>Nutrisi harian</h3><p>Susun menu dan biaya makan pagi, siang, serta malam.</p><button class="btn btn-primary" onclick="location.hash='nutrition'">Buka nutrisi</button></article></div><div class="col-12 col-lg-4"><article class="card border-0 shadow-sm h-100 p-4 tile"><div class="icon">◷</div><h3>Audit waktu</h3><p>Bandingkan jam aktivitas setiap hari dengan total 168 jam seminggu.</p><button class="btn btn-primary" onclick="location.hash='time'">Buka audit waktu</button></article></div><div class="col-12 col-lg-4"><article class="card border-0 shadow-sm h-100 p-4 tile"><div class="icon">◫</div><h3>Pengeluaran aktual</h3><p>Catat transaksi dan periksa kategori over atau under budget.</p><button onclick="location.hash='expenses'">Buka pengeluaran</button></article></div></div>`}else if(page==='budgeting'){html=heading('Budgeting bulanan','Monthly Budgeting Card · catat nominal dalam rupiah.')+`<section class="card border-0 shadow-sm p-4 mb-4"><div class="row g-3"><div class="col-12 col-md-4 field"><label>Nama</label>${input('time-name','text','Nama peserta')}</div><div class="col-12 col-md-4 field"><label>Usia (tahun)</label>${input('time-age','number','0')}</div><div class="col-12 col-md-4 field"><label>Profesi</label>${input('time-job','text','Profesi')}</div></div></section><div class="toolbar mb-4"><div><label>Bulan pencatatan</label><input type="month" data-key="budget-period" value="${esc(selectedMonth())}"></div></div>`+budgetGroups.map((g,gi)=>`<section class="card border-0 shadow-sm p-4 mb-4 group"><h2>${g[0]}</h2><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Detail</th><th style="width:210px">Nominal (Rp)</th><th class="num">% dari pemasukan</th><th class="no-pdf"></th></tr></thead><tbody>${bids(gi).map(id=>`<tr><td>${nameInput(gi,id)}</td><td>${input(bkey(gi,id),'number','0')}</td><td class="num">${s.b[0]?Math.round(n(bkey(gi,id))/s.b[0]*100):0}%</td><td class="no-pdf"><button type="button" class="rm-item" data-rm="${gi}:${id}" aria-label="Hapus item">&times;</button></td></tr>`).join('')}</tbody></table></div><button type="button" class="add-item" data-add="${gi}">+ Tambah item</button><div class="summary alert alert-light border"><span>Total ${g[0].toLowerCase()}</span><strong>${money(s.b[gi])}</strong></div></section>`).join('')+`<div class="card border-0 shadow-sm p-4 mb-4"><div class="summary alert alert-light border"><span>Total pengeluaran</span><strong>${money(s.expenses)}</strong></div><div class="summary alert alert-light border"><span>Selisih pemasukan − pengeluaran</span><strong>${money(s.b[0]-s.expenses)}</strong></div></div>`}else if(page==='expenses'){html=heading('Pengeluaran aktual','Catat transaksi berdasarkan kategori anggaran dan tinjau hasil bulanan.')+`<div class="toolbar"><div><label>Bulan evaluasi</label><input type="month" data-key="budget-period" value="${esc(selectedMonth())}"></div></div>`+expenseForm()+evaluation(s)+expenseList()}else if(page==='nutrition'){html=heading('Nutrisi harian','Catat menu dan harga untuk setiap waktu makan.')+`<section class="card border-0 shadow-sm p-4 mb-4"><div class="row g-3"><div class="col-12 col-md-4 field"><label>Nama</label>${input('time-name','text','Nama peserta')}</div><div class="col-12 col-md-4 field"><label>Usia (tahun)</label>${input('time-age','number','0')}</div><div class="col-12 col-md-4 field"><label>Profesi</label>${input('time-job','text','Profesi')}</div></div></section><div class="toolbar mb-4"><div><label>Tanggal pencatatan</label><input type="date" data-key="nutrition-date" value="${esc(val('nutrition-date')||new Date().toISOString().slice(0,10))}"></div></div>`+meals.map((meal,m)=>`<section class="card border-0 shadow-sm p-4 mb-4 group"><h2>${meal}</h2><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Jenis nutrisi</th><th>Nama menu</th><th style="width:190px">Harga (Rp)</th><th class="no-pdf"></th></tr></thead><tbody>${nids(m).map(id=>`<tr><td>${typeSelect(m,id)}</td><td>${input(`n-${m}-${id}-menu`,'text','Isi nama menu')}</td><td>${input(`n-${m}-${id}-price`,'number','0')}</td><td class="no-pdf"><button type="button" class="rm-item" data-nrm="${m}:${id}" aria-label="Hapus item">&times;</button></td></tr>`).join('')}</tbody></table></div><button type="button" class="add-item" data-nadd="${m}">+ Tambah item</button><div class="summary alert alert-light border"><span>Total harga ${meal.toLowerCase()}</span><strong>${money(nids(m).reduce((a,id)=>a+n(`n-${m}-${id}-price`),0))}</strong></div></section>`).join('')+`<div class="card border-0 shadow-sm p-4 summary"><span>Total biaya makan hari ini</span><strong>${money(s.nutrition)}</strong></div>`}else{html=heading('Audit waktu','Catat jumlah jam per aktivitas dalam satu minggu.')+`<section class="card border-0 shadow-sm p-4 mb-4"><div class="row g-3"><div class="col-12 col-md-4 field"><label>Nama</label>${input('time-name','text','Nama peserta')}</div><div class="col-12 col-md-4 field"><label>Usia (tahun)</label>${input('time-age','number','0')}</div><div class="col-12 col-md-4 field"><label>Profesi</label>${input('time-job','text','Profesi')}</div></div></section><section class="card border-0 shadow-sm p-4 mb-4"><h2>Aktivitas mingguan</h2><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Aktivitas</th>${days.map(d=>`<th class="num">${d}</th>`).join('')}<th class="num">Total jam</th><th class="num">% dari 168 jam</th><th class="num">Usia × porsi waktu</th></tr></thead><tbody>${acts.map((act,a)=>`<tr><td>${act}</td>${days.map((_,d)=>`<td>${input(`t-${a}-${d}`,'number','0')}</td>`).join('')}<td class="num">${hour(s.times[a])}</td><td class="num">${(s.times[a]/168*100).toFixed(1)}%</td><td class="num">${hour(n('time-age')*s.times[a]/168)}</td></tr>`).join('')}<tr><th>Total jam per hari</th>${days.map((_,d)=>`<th class="num ${acts.reduce((v,__,a)=>v+n(`t-${a}-${d}`),0)>24?'warning':''}">${hour(acts.reduce((v,__,a)=>v+n(`t-${a}-${d}`),0))}</th>`).join('')}<th class="num">${hour(s.total)}</th><th class="num">${(s.total/168*100).toFixed(1)}%</th><th></th></tr></tbody></table></div><p class="hint">Setiap hari tersedia 24 jam; satu minggu tersedia 168 jam. “Usia × porsi waktu” mengikuti perhitungan pada worksheet sumber.</p></section>`}document.getElementById('app').innerHTML=html+`<p class="hint">Visual awal: data tersimpan hanya di browser perangkat ini. Belum ada akun karyawan atau penyimpanan terpusat.</p><span class="saved" aria-live="polite"></span>`}document.addEventListener('submit',e=>{if(e.target.id!=='expenseForm')return;e.preventDefault();const f=new FormData(e.target),amount=Number(f.get('amount')),date=String(f.get('date')||'');if(!date||!Number.isFinite(amount)||amount<=0)return;state.actualExpenses=actualItems().concat([{id:Date.now()+Math.random(),date,category:Number(f.get('category')),amount,note:String(f.get('note')||'').trim()}]);state['budget-period']=date.slice(0,7);save();render()});document.addEventListener('click',e=>{const btn=e.target.closest('[data-delete]');if(!btn)return;state.actualExpenses=actualItems().filter(x=>String(x.id)!==btn.dataset.delete);save();render()});document.addEventListener('input',e=>{if(e.target.dataset.key){if(e.target.inputMode==='decimal'){const raw=e.target.value,caret=e.target.selectionStart,clean=raw.replace(/,/g,'.').replace(/[^0-9.]/g,'');if(clean!==raw){const before=raw.slice(0,caret).replace(/,/g,'.').replace(/[^0-9.]/g,'').length;e.target.value=clean;e.target.setSelectionRange(before,before)}}state[e.target.dataset.key]=e.target.value;save();let pos=e.target.selectionStart,key=e.target.dataset.key;render();let target=[...document.querySelectorAll('[data-key]')].find(el=>el.dataset.key===key);if(target){target.focus();if(pos!==null&&target.type==='text')target.setSelectionRange(pos,pos)}}});document.addEventListener('click',e=>{const a=e.target.closest('[data-add]'),r=e.target.closest('[data-rm]');if(a){const gi=Number(a.dataset.add),id='c'+Date.now().toString(36);state.budgetIds={...(state.budgetIds||{}),[gi]:[...bids(gi),id]};save();render();const el=document.querySelector(`[data-key="${bnamekey(gi,id)}"]`);if(el)el.focus()}else if(r){const [g,id]=r.dataset.rm.split(':'),gi=Number(g);state.budgetIds={...(state.budgetIds||{}),[gi]:bids(gi).filter(x=>x!==id)};delete state[bnamekey(gi,id)];save();render()}});document.addEventListener('click',e=>{const a=e.target.closest('[data-nadd]'),r=e.target.closest('[data-nrm]');if(a){const m=Number(a.dataset.nadd),id='c'+Date.now().toString(36);state.nutIds={...(state.nutIds||{}),[m]:[...nids(m),id]};save();render();const el=document.querySelector(`[data-key="n-${m}-${id}-menu"]`);if(el)el.focus()}else if(r){const [g,id]=r.dataset.nrm.split(':'),m=Number(g);state.nutIds={...(state.nutIds||{}),[m]:nids(m).filter(x=>x!==id)};for(const f of ['menu','price','type'])delete state[`n-${m}-${id}-${f}`];save();render()}});addEventListener('hashchange',render);render();
